#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeSet;

    #[test]
    fn one_hundred_named_nonempty_regions() {
        assert_eq!(VOCABULARY_REGIONS.len(), 100);
        let titles: BTreeSet<_> = VOCABULARY_REGIONS.iter().map(|r| r.title).collect();
        assert_eq!(titles.len(), 100);
        for (index, region) in VOCABULARY_REGIONS.iter().enumerate() {
            assert_eq!(region.id as usize, index + 1);
            assert!(!region.domain.is_empty());
            assert!(!region.hanzi.is_empty());
            assert!(!region.source_entries.is_empty());
            assert!(!region.readings.is_empty());
            assert_eq!(region.hanzi.len(), region.hanzi.iter().collect::<BTreeSet<_>>().len());
        }
    }

    #[test]
    fn source_record_membership_is_exhaustive_and_disjoint() {
        let mut indices: Vec<u16> = VOCABULARY_REGIONS.iter()
            .flat_map(|region| region.source_entries.iter().copied()).collect();
        indices.sort_unstable();
        assert_eq!(indices.len(), 11_494);
        for (index, id) in indices.iter().enumerate() {
            assert_eq!(*id as usize, index);
        }
    }

    #[test]
    fn all_hsk_readings_are_unique() {
        let mut readings = BTreeSet::new();
        for region in &VOCABULARY_REGIONS {
            for reading in region.readings {
                assert!(readings.insert(*reading));
            }
        }
        assert_eq!(readings.len(), 12_188);
    }
}
